"""Generate docs/reference/ from the code, so the reference can never drift from it.

uv run python scripts/make_reference.py            # formulas and checks (about 2 minutes)
uv run python scripts/make_reference.py --formulas # formulas only
"""

from __future__ import annotations

import sys
from pathlib import Path

from catlab.provenance import cite
from catlab.theory import FORMULAS

OUT = Path(__file__).resolve().parents[1] / "docs" / "reference"


def formulas_md() -> str:
    lines = [
        "# Formulas",
        "",
        "Generated by `scripts/make_reference.py` from `src/catlab/theory/`. Do not edit.",
        "",
    ]
    for f in FORMULAS.values():
        lines += [f"## {f.title}", "", f"`{f.key}`", "", "```latex", f.latex, "```", ""]
        lines += [f"Valid when: {f.valid_when}", ""]
        for s in f.sources:
            entry = cite(s.key)
            where = entry.get("doi") and f"https://doi.org/{entry['doi']}" or entry.get("url", "")
            link = f"[{s.key}]({where})" if where else s.key
            note = f" {s.note}" if s.note else ""
            lines.append(f"- {link}, {s.locator} ({s.kind.value}).{note}")
        lines.append("")
    return "\n".join(lines)


def checks_md() -> str:
    from catlab.checks import run_all

    lines = [
        "# Checks: theory vs simulation",
        "",
        "Generated by `scripts/make_reference.py` from `src/catlab/checks/`. Do not edit.",
        "",
        "Expected is the verdict predicted from the formula's validity range before running.",
        "",
        "| Check | Regime | Theory | Simulation | Rel. error | Tolerance | Verdict | Expected |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for r in run_all():
        regime = r.regime.replace("|", "\\|")
        lines.append(
            f"| `{r.key}` | {regime} | {r.theory:.6g} | {r.sim:.6g} | {r.rel_error:.2g} "
            f"| {r.rel_tol:g} | {r.verdict.value} | {r.expected.value} |"
        )
    return "\n".join(lines) + "\n"


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "formulas.md").write_text(formulas_md(), encoding="utf-8")
    if "--formulas" not in sys.argv:
        (OUT / "checks.md").write_text(checks_md(), encoding="utf-8")


if __name__ == "__main__":
    main()
